/* LINER-UPDATE id="board-annotations-v1" title="خانه‌ی سبز/قرمز و فلش دستی روی صفحه (ویرایش) + نمایش در مرور" base="v6" */
(function () {
  if (window.__LINER_ANN) return;
  window.__LINER_ANN = 1;

  var NS = 'http://www.w3.org/2000/svg', F = 'abcdefgh';
  var COL = { g: '#16a34a', r: '#dc2626' };
  var ANN = { mode: null, start: null, cur: null };

  LU.css(
    '.board .sq.ang{background-image:linear-gradient(rgba(34,197,94,.62),rgba(34,197,94,.62))}' +
    '.board .sq.anr{background-image:linear-gradient(rgba(239,68,68,.62),rgba(239,68,68,.62))}' +
    '#anbar{margin:8px 0}' +
    '#anbar[hidden]{display:none}' +
    '#anbar .anr1{display:flex;gap:6px;flex-wrap:wrap}' +
    '#anbar button{flex:1 1 auto;min-width:0}' +
    '#anbar button.on{outline:2px solid var(--acc)}' +
    '#anbar .g{background:#16a34a;color:#fff}#anbar .r{background:#dc2626;color:#fff}'
  );

  /* ---------- نوار ابزار (فقط در ویرایش) ---------- */
  var fs2 = $('fs2'), bd2 = $('bd2');
  if (!fs2 || !bd2) throw new Error('عناصر ویرایش پیدا نشد');
  var btn = document.createElement('button');
  btn.type = 'button'; btn.id = 'anbtn'; btn.textContent = '🎨 خانه و فلش';
  fs2.insertAdjacentElement('afterend', btn);
  var bar = document.createElement('div');
  bar.id = 'anbar'; bar.hidden = true;
  bar.innerHTML =
    '<div class="anr1">' +
    '<button type="button" class="g" data-m="sg">■ خانه سبز</button>' +
    '<button type="button" class="r" data-m="sr">■ خانه قرمز</button>' +
    '<button type="button" class="g" data-m="ag">➚ فلش سبز</button>' +
    '<button type="button" class="r" data-m="ar">➚ فلش قرمز</button>' +
    '<button type="button" data-m="clr">پاک‌کردن این پوزیشن</button></div>' +
    '<div class="meta" id="anh" style="margin-top:4px"></div>';
  bd2.parentNode.insertAdjacentElement('afterend', bar);

  var HINT = {
    sg: 'روی هر خانه بزن تا سبز بشه (دوباره بزنی برمی‌داره).',
    sr: 'روی هر خانه بزن تا قرمز بشه (دوباره بزنی برمی‌داره).',
    ag: 'از خانه‌ی مبدأ تا مقصد بکش تا فلش سبز ساخته بشه (دوباره همونو بکشی برمی‌داره).',
    ar: 'از خانه‌ی مبدأ تا مقصد بکش تا فلش قرمز ساخته بشه (دوباره همونو بکشی برمی‌داره).'
  };
  function sync() {
    Array.prototype.forEach.call(bar.querySelectorAll('[data-m]'), function (b) { b.classList.toggle('on', b.dataset.m === ANN.mode); });
    $('anh').textContent = ANN.mode ? HINT[ANN.mode] : 'یک ابزار انتخاب کن. علامت‌ها به همین پوزیشن می‌چسبن و در مرور هم نمایش داده می‌شن.';
    bd2.style.touchAction = ANN.mode ? 'none' : '';
    btn.classList.toggle('on', !bar.hidden);
  }
  btn.onclick = function () { bar.hidden = !bar.hidden; if (bar.hidden) ANN.mode = null; sync(); };
  bar.onclick = function (e) {
    var m = e.target.dataset && e.target.dataset.m; if (!m) return;
    if (m === 'clr') {
      var n = curNode();
      if (n) { delete n.hl; delete n.ar; draw(E); toast('علامت‌های این پوزیشن پاک شد.'); }
      return;
    }
    ANN.mode = (ANN.mode === m) ? null : m; sync();
  };
  // هر بار ویرایش تازه باز می‌شود، ابزار خاموش شروع شود تا حرکت مهره‌ها قفل نماند
  var _openEdit = window.openEdit;
  window.openEdit = function () { ANN.mode = null; ANN.start = null; sync(); return _openEdit.apply(this, arguments); };

  /* ---------- داده: روی گره‌ی فعلی درخت ---------- */
  function curNode() { return (E && !E.an) ? E.node : null; }
  function toggleSq(sq, c) {
    var n = curNode(); if (!n) return;
    n.hl = n.hl || {};
    if (n.hl[sq] === c) delete n.hl[sq]; else n.hl[sq] = c;
    if (!Object.keys(n.hl).length) delete n.hl;
  }
  function toggleArrow(f, t, c) {
    var n = curNode(); if (!n || f === t) return;
    n.ar = n.ar || [];
    var i, hit = -1;
    for (i = 0; i < n.ar.length; i++) if (n.ar[i].f === f && n.ar[i].t === t) hit = i;
    if (hit > -1) { if (n.ar[hit].c === c) n.ar.splice(hit, 1); else n.ar[hit].c = c; }
    else n.ar.push({ f: f, t: t, c: c });
    if (!n.ar.length) delete n.ar;
  }

  /* ---------- نمایش (ویرایش و مرور) ---------- */
  function ensureSvg(k, bd) {
    var s = document.getElementById('an' + k);
    if (!s) {
      s = document.createElementNS(NS, 'svg');
      s.id = 'an' + k; s.setAttribute('viewBox', '0 0 80 80'); s.setAttribute('aria-hidden', 'true');
      s.style.cssText = 'position:absolute;pointer-events:none;z-index:3;display:none';
      bd.parentNode.appendChild(s);
    }
    return s;
  }
  function arrow(A, Bp, col, op) {
    var dx = Bp[0] - A[0], dy = Bp[1] - A[1], n = Math.sqrt(dx * dx + dy * dy) || 1, ux = dx / n, uy = dy / n, nx = -uy, ny = ux;
    var sw = 1.25, hw = 3.1, hl = 3.9, bx = Bp[0] - ux * hl, by = Bp[1] - uy * hl;
    var P = [[A[0] + nx * sw, A[1] + ny * sw], [bx + nx * sw, by + ny * sw], [bx + nx * hw, by + ny * hw], [Bp[0], Bp[1]], [bx - nx * hw, by - ny * hw], [bx - nx * sw, by - ny * sw], [A[0] - nx * sw, A[1] - ny * sw]];
    return '<polygon points="' + P.map(function (z) { return z[0].toFixed(2) + ',' + z[1].toFixed(2); }).join(' ') + '" fill="' + col + '" fill-opacity="' + op + '"/>';
  }
  function ptOf(sq, flip) { var f = F.indexOf(sq[0]), r = +sq[1]; return [((flip ? 7 - f : f) + .5) * 10, ((flip ? r - 1 : 8 - r) + .5) * 10]; }

  function draw(b) {
    if (!b || !b.el) return;
    var id = b.el.id, k = id === 'bd2' ? '2' : id === 'bd3' ? '3' : null; if (!k) return;
    Array.prototype.forEach.call(b.el.querySelectorAll('.sq'), function (s) { s.classList.remove('ang', 'anr'); });
    var svg = ensureSvg(k, b.el);
    var ok = (b === window.E) ? !b.an : (b === window.V ? !b.free : false);   // در تحلیل آزاد، پوزیشن همان گره‌ی درخت نیست
    var n = ok ? b.node : null;
    var h = '';
    if (n) {
      var flip = b.color === 'b';
      if (n.hl) Object.keys(n.hl).forEach(function (sq) {
        var el = b.el.querySelector('[data-s="' + sq + '"]'); if (el) el.classList.add(n.hl[sq] === 'r' ? 'anr' : 'ang');
      });
      (n.ar || []).forEach(function (a) { h += arrow(ptOf(a.f, flip), ptOf(a.t, flip), COL[a.c] || COL.g, .85); });
      if (k === '2' && ANN.start && ANN.cur && ANN.start !== ANN.cur && (ANN.mode === 'ag' || ANN.mode === 'ar'))
        h += arrow(ptOf(ANN.start, flip), ptOf(ANN.cur, flip), COL[ANN.mode === 'ar' ? 'r' : 'g'], .5);   // پیش‌نمایش هنگام کشیدن
    } else if (k === '2' && ANN.start && ANN.cur && ANN.start !== ANN.cur && E && !E.an && (ANN.mode === 'ag' || ANN.mode === 'ar')) {
      h += arrow(ptOf(ANN.start, E.color === 'b'), ptOf(ANN.cur, E.color === 'b'), COL[ANN.mode === 'ar' ? 'r' : 'g'], .5);
    }
    if (!h) { svg.style.display = 'none'; svg.innerHTML = ''; return; }
    svg.style.left = b.el.offsetLeft + 'px'; svg.style.top = b.el.offsetTop + 'px';
    svg.style.width = b.el.offsetWidth + 'px'; svg.style.height = b.el.offsetHeight + 'px';
    svg.innerHTML = h; svg.style.display = 'block';
  }

  var _render = window.render;
  window.render = function () {
    var r = _render.apply(this, arguments);
    try { if (window.B === window.E || window.B === window.V) draw(window.B); } catch (e) { console.error(e); }
    return r;
  };
  var _ea = window.engArrows;
  window.engArrows = function () {            // همان جاهایی که فلش انجین دوباره چیده می‌شود (چرخش صفحه، تمام‌صفحه)
    var r = _ea.apply(this, arguments);
    try { draw(window.E); draw(window.V); } catch (e) { }
    return r;
  };

  /* ---------- کشیدن روی صفحه‌ی ویرایش ---------- */
  function sqAt(x, y) {
    var el = document.elementFromPoint(x, y); el = el && el.closest && el.closest('.sq');
    return (el && el.parentNode === bd2) ? el.dataset.s : null;
  }
  bd2.addEventListener('pointerdown', function (e) {
    if (!ANN.mode || !E || E.an) return;
    e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation();
    ANN.start = sqAt(e.clientX, e.clientY); ANN.cur = ANN.start;
  }, true);
  bd2.addEventListener('click', function (e) {              // جلوگیری از انتخاب/حرکت مهره‌ی عادی در حالت ابزار
    if (ANN.mode && E && !E.an) { e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation(); }
  }, true);
  document.addEventListener('pointermove', function (e) {
    if (!ANN.start) return;
    var s = sqAt(e.clientX, e.clientY);
    if (s && s !== ANN.cur) { ANN.cur = s; draw(E); }
  }, true);
  document.addEventListener('pointerup', function (e) {
    if (!ANN.start) return;
    var from = ANN.start, to = sqAt(e.clientX, e.clientY) || ANN.cur;
    ANN.start = ANN.cur = null;
    if (from && to && E && !E.an) {
      if (ANN.mode === 'sg' || ANN.mode === 'sr') { if (from === to) toggleSq(from, ANN.mode === 'sr' ? 'r' : 'g'); }
      else if (from !== to) toggleArrow(from, to, ANN.mode === 'ar' ? 'r' : 'g');
    }
    draw(E);
  }, true);
  document.addEventListener('pointercancel', function () { if (ANN.start) { ANN.start = ANN.cur = null; draw(E); } }, true);
  window.addEventListener('resize', function () { try { draw(window.E); draw(window.V); } catch (e) { } });

  sync();
})();

/* LINER-UPDATE id="capture-fx-arrow-labels-v1" title="انیمیشن خورد شدن مهره‌ی کپچرشده + شماره‌ی خط انجین روی فلش‌ها" base="v6" */
(function () {
  if (window.__LINER_FXAL) return;
  window.__LINER_FXAL = 1;

  /* ================= 1) شماره‌ی خط انجین نزدیک نوک فلش ================= */
  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  var TIP_GAP = 0.8;   // فاصله‌ی مرکز عدد از نوک فلش (واحد: ۱/۱۰ خانه)؛ کمتر = عدد بیشتر روی فلش می‌شینه
  // زاویه‌ی کجیِ هر عدد منحصربه‌فرد است (برای هر شماره‌ی خط همیشه همان زاویه)
  function tilt(i) {
    var t = ((i * 47) % 53) / 52, ang = -24 + t * 48;         // بین -۲۴ تا +۲۴ درجه
    var sg = ang < 0 ? -1 : 1;
    return sg * (7 + Math.abs(ang) * 0.72);                   // حداقل ۷ درجه کج؛ هیچ عددی صاف نمی‌مونه
  }
  // برچسب‌ها اول جمع می‌شن و آخر کار (بعد از همه‌ی فلش‌ها) چیده می‌شن تا روی هم نیفتن
  var LB = [];
  window.engLblReset = function () { LB = []; };
  window.engLbl = function (i, col, Bp, ux, uy) { LB.push({ i: i, col: col, Bp: Bp, ux: ux, uy: uy }); return ''; };

  var BW = 2.6, BH = 3.1;   // اندازه‌ی تقریبی جعبه‌ی هر عدد؛ نزدیک‌تر از این یعنی روی هم افتاده
  function hit(x, y, placed) {
    for (var k = 0; k < placed.length; k++)
      if (Math.abs(placed[k][0] - x) < BW && Math.abs(placed[k][1] - y) < BH) return true;
    return false;
  }
  window.engLblFlush = function () {
    var out = '', placed = [];
    LB.sort(function (a, b) { return a.i - b.i; });            // خط ۱ اولویت دارد و جای ایده‌آلش را می‌گیرد
    LB.forEach(function (L) {
      var ux = L.ux, uy = L.uy, nx = -uy, ny = ux;
      var bx = L.Bp[0] + ux * TIP_GAP, by = L.Bp[1] + uy * TIP_GAP;
      // کاندیداها: جای اصلی، سپس عقب‌تر روی خود فلش، سپس کنار فلش
      var C = [[0, 0], [-2.8, 0], [-5.6, 0], [0, 2.8], [0, -2.8], [-2.8, 2.8], [-2.8, -2.8], [-5.6, 2.8], [-5.6, -2.8], [0, 5.6], [0, -5.6], [-8.4, 0]];
      var x = clamp(bx, 2, 78), y = clamp(by, 2.4, 77.6), k;
      for (k = 0; k < C.length; k++) {
        var cx = clamp(bx + ux * C[k][0] + nx * C[k][1], 2, 78), cy = clamp(by + uy * C[k][0] + ny * C[k][1], 2.4, 77.6);
        if (!hit(cx, cy, placed)) { x = cx; y = cy; break; }
      }
      placed.push([x, y]);
      var dark = (L.col === '#000'), xs = x.toFixed(2), ys = y.toFixed(2);
      out += '<text x="' + xs + '" y="' + ys + '" transform="rotate(' + tilt(L.i).toFixed(1) + ' ' + xs + ' ' + ys + ')"' +
        ' font-size="2.7" font-weight="700" text-anchor="middle" dominant-baseline="central"' +
        ' fill="' + L.col + '" fill-opacity="' + (dark ? .85 : 1) + '" stroke="' + (dark ? 'rgba(255,255,255,.85)' : 'rgba(0,0,0,.6)') + '" stroke-width=".5" paint-order="stroke"' +
        ' style="font-family:system-ui,sans-serif">' + L.i + '</text>';
    });
    LB = [];
    return out;
  };
  try {
    LU.patch('engArrows', "ks.slice().reverse().forEach(function(i){", "engLblReset();ks.slice().reverse().forEach(function(i){");
    LU.patch('engArrows', '+\'" fill-opacity="\'+op+\'"/>\';', '+\'" fill-opacity="\'+op+\'"/>\'+engLbl(i,col,Bp,ux,uy);');
    LU.patch('engArrows', "a.innerHTML=h;a.style.display='block';", "a.innerHTML=h+engLblFlush();a.style.display='block';");
  } catch (e) { console.error('patch engArrows', e); }

  /* ================= 2) خورد شدن مهره هنگام کپچر ================= */
  function rnd(a, b) { return a + Math.random() * (b - a); }

  // مثلث‌های نامنظم روی مهره (شبکه‌ی ۳×۳ با رأس‌های جابه‌جاشده، هر خانه = ۲ تکه)
  function shards() {
    var n = 3, V = [], i, j, out = [];
    for (j = 0; j <= n; j++) { V[j] = []; for (i = 0; i <= n; i++) {
      var edge = (i === 0 || j === 0 || i === n || j === n);
      V[j][i] = [i / n * 100 + (edge ? 0 : rnd(-9, 9)), j / n * 100 + (edge ? 0 : rnd(-9, 9))];
    } }
    for (j = 0; j < n; j++) for (i = 0; i < n; i++) {
      var a = V[j][i], b = V[j][i + 1], c = V[j + 1][i + 1], d = V[j + 1][i];
      if (Math.random() < .5) { out.push([a, b, c]); out.push([a, c, d]); }
      else { out.push([a, b, d]); out.push([b, c, d]); }
    }
    return out;
  }
  function poly(t) { return 'polygon(' + t.map(function (p) { return p[0].toFixed(1) + '% ' + p[1].toFixed(1) + '%'; }).join(',') + ')'; }

  function shatter(cls, sqEl, DELAY) {
    if (DELAY == null) DELAY = 110;
    var r = sqEl.getBoundingClientRect(), W = r.width;
    if (!W) return;
    var box = document.createElement('div');
    box.setAttribute('aria-hidden', 'true');
    box.style.cssText = 'position:fixed;left:' + r.left + 'px;top:' + r.top + 'px;width:' + W + 'px;height:' + r.height + 'px;pointer-events:none;z-index:60;overflow:visible';
    var parts = [];

    shards().forEach(function (t) {
      var s = document.createElement('div');
      s.className = 'pc ' + cls;
      s.style.cssText = 'position:absolute;left:0;top:0;width:100%;height:100%;clip-path:' + poly(t) + ';-webkit-clip-path:' + poly(t) + ';will-change:transform,opacity';
      box.appendChild(s);
      var cx = (t[0][0] + t[1][0] + t[2][0]) / 300 - .5, cy = (t[0][1] + t[1][1] + t[2][1]) / 300 - .5;
      var dx = (cx * 2.6 + rnd(-.35, .35)) * W, dy = (cy * 2.2 + rnd(-.1, .5)) * W + rnd(.35, 1.0) * W;   // به بیرون و کمی به پایین (جاذبه)
      var rot = rnd(-260, 260), dur = rnd(520, 780);
      parts.push([s, dx, dy, rot, dur]);
    });

    // جرقه‌ی برخورد + حلقه‌ی ضربه
    var ring = document.createElement('div');
    ring.style.cssText = 'position:absolute;left:50%;top:50%;width:' + W * .9 + 'px;height:' + W * .9 + 'px;margin:' + (-W * .45) + 'px 0 0 ' + (-W * .45) + 'px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.85) 0%,rgba(255,214,102,.55) 38%,rgba(255,214,102,0) 70%);opacity:0';
    box.appendChild(ring);
    var sparks = [];
    for (var k = 0; k < 9; k++) {
      var sp = document.createElement('div'), sz = rnd(.06, .12) * W, ang = rnd(0, Math.PI * 2), dist = rnd(.5, 1.3) * W;
      sp.style.cssText = 'position:absolute;left:50%;top:50%;width:' + sz + 'px;height:' + sz + 'px;margin:' + (-sz / 2) + 'px 0 0 ' + (-sz / 2) + 'px;border-radius:50%;background:' + (k % 2 ? '#ffd666' : '#fff') + ';opacity:0';
      box.appendChild(sp);
      sparks.push([sp, Math.cos(ang) * dist, Math.sin(ang) * dist]);
    }
    document.body.appendChild(box);

    parts.forEach(function (p) {
      p[0].animate([
        { transform: 'translate(0,0) rotate(0deg) scale(1)', opacity: 1, offset: 0 },
        { transform: 'translate(' + p[1] * .35 + 'px,' + p[2] * .2 + 'px) rotate(' + p[3] * .3 + 'deg) scale(1)', opacity: 1, offset: .25 },
        { transform: 'translate(' + p[1] + 'px,' + p[2] + 'px) rotate(' + p[3] + 'deg) scale(.55)', opacity: 0, offset: 1 }
      ], { duration: p[4], delay: DELAY, easing: 'cubic-bezier(.2,.7,.3,1)', fill: 'both' });
    });
    ring.animate([{ transform: 'scale(.3)', opacity: .95 }, { transform: 'scale(1.7)', opacity: 0 }],
      { duration: 360, delay: DELAY, easing: 'ease-out', fill: 'both' });
    sparks.forEach(function (s) {
      s[0].animate([{ transform: 'translate(0,0) scale(1)', opacity: 1 }, { transform: 'translate(' + s[1] + 'px,' + s[2] + 'px) scale(.2)', opacity: 0 }],
        { duration: rnd(380, 560), delay: DELAY, easing: 'cubic-bezier(.1,.7,.3,1)', fill: 'both' });
    });
    setTimeout(function () { if (box.parentNode) box.parentNode.removeChild(box); }, DELAY + 1000);
  }

  var REDUCED = function () { return !!(window.matchMedia && matchMedia('(prefers-reduced-motion:reduce)').matches); };

  var _anim = window.anim;
  window.anim = function (m, el) {
    var jp = !!window.JP, drag = !!window.noAnim;            // قبل از ریست شدن توسط anim اصلی خوانده می‌شود
    var r = _anim.apply(this, arguments);
    try {
      if (jp || !m || !el || !el.animate || REDUCED()) return r;   // پرش بین حرکت‌ها (JP) بی‌انیمیشن؛ اما درگ دستی (noAnim) خورد می‌شود
      var fl = m.flags || '', ep = fl.indexOf('e') > -1, cap = m.captured || (ep ? 'p' : '');
      if (!cap) return r;
      var sq = ep ? (m.to[0] + m.from[1]) : m.to;              // کپچر معمولی: خانه‌ی مقصد؛ آنپاسان: خانه‌ی پیاده‌ی حریف
      var sqEl = el.querySelector('[data-s="' + sq + '"]');
      if (sqEl) shatter((m.color === 'w' ? 'b' : 'w') + String(cap).toUpperCase(), sqEl, drag ? 0 : 110);
    } catch (e) { console.error(e); }
    return r;
  };

  /* ================= 3) کیش و مات: لرزش شاه در کیش، واژگون شدن شاه در مات ================= */
  function findKing(g, col) {
    var bd = g.board(), r, c, p;
    for (r = 0; r < 8; r++) for (c = 0; c < 8; c++) { p = bd[r][c]; if (p && p.type === 'k' && p.color === col) return 'abcdefgh'[c] + (8 - r); }
    return null;
  }
  function ring(sqEl, color, delay) {
    var r = sqEl.getBoundingClientRect(), W = r.width; if (!W) return;
    var d = document.createElement('div');
    d.setAttribute('aria-hidden', 'true');
    d.style.cssText = 'position:fixed;left:' + (r.left - W * .1) + 'px;top:' + (r.top - W * .1) + 'px;width:' + W * 1.2 + 'px;height:' + W * 1.2 + 'px;border-radius:50%;pointer-events:none;z-index:60;' +
      'background:radial-gradient(circle,' + color + ' 0%,rgba(255,0,0,0) 68%);opacity:0';
    document.body.appendChild(d);
