/* LINER-UPDATE id="gx-copy-pgn-v1" title="کپی PGN گره انتخاب‌شده در نمودار (از اول تا آخر)" base="v6" */
(function () {
  if (window.__LINER_CPGN) return;
  window.__LINER_CPGN = 1;

  // PGN گره انتخاب‌شده: مسیر از اول بازی تا گره + همه‌ی ادامه‌ها و شاخه‌های زیرش تا آخر
  function nodePgn(X) {
    var sel = X && X.sel;
    if (!sel) return '';
    var fen0 = X.fen0 || START, f = fen0.split(' ');
    var chain = [], n = sel;
    while (n && n.par) { chain.unshift(n); n = n.par; }
    function cv(k) { return { san: k.san, lb: k.lb, c: (k.kids || []).map(cv) }; }
    var root = { c: [] }, cur = root;
    chain.forEach(function (p) {
      var o = { san: p.san, lb: p.lb, c: [] };
      cur.c.push(o); cur = o;
    });
    cur.c = (sel.kids || []).map(cv);
    var body = ser(root, f[1] || 'w', parseInt(f[5]) || 1, true);
    if (!body) return '';
    var head = fen0 !== START ? '[SetUp "1"]\n[FEN "' + fen0 + '"]\n\n' : '';
    return head + body;
  }

  function copyText(t) {
    return new Promise(function (ok, bad) {
      function fallback() {
        try {
          var ta = document.createElement('textarea');
          ta.value = t; ta.setAttribute('readonly', '');
          ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0';
          document.body.appendChild(ta); ta.select(); ta.setSelectionRange(0, t.length);
          var r = document.execCommand('copy');
          document.body.removeChild(ta);
          r ? ok() : bad();
        } catch (e) { bad(e); }
      }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(t).then(ok, fallback);
      else fallback();
    });
  }

  function doCopy(X, btn) {
    var t = nodePgn(X);
    if (!t) { toast('چیزی برای کپی نیست.'); return; }
    var old = btn.dataset.t || btn.textContent;
    btn.dataset.t = old;
    copyText(t).then(function () {
      btn.textContent = '✓ کپی شد';
      toast('PGN کپی شد.');
    }, function () {
      window.prompt('کپی خودکار نشد؛ متن را دستی کپی کن:', t);
    }).then(function () {
      setTimeout(function () { btn.textContent = old; }, 1500);
    });
  }

  function mk(getX) {
    var b = document.createElement('button');
    b.type = 'button'; b.className = 'gxcp'; b.textContent = '📋 کپی PGN';
    b.onclick = function (e) { e.stopPropagation(); doCopy(getX(), b); };
    return b;
  }

  // نمودار دسته‌ی اصلی
  var zo = document.getElementById('gvzo');
  if (zo) zo.insertAdjacentElement('beforebegin', mk(function () { return GV; }));

  // نمودارهای داخل ویرایش و مرور
  ['e', 'v'].forEach(function (k) {
    var w = document.getElementById('gxw_' + k);
    var tb = w && w.querySelector('.gvtb');
    if (tb) tb.appendChild(mk(function () { return GX[k]; }));
  });
})();

