/* LINER-UPDATE id="move-lines-db-v1" title="انتخاب دیتابیس در ایجاد + انتقال لاین‌ها بین دسته‌ها و دیتابیس" base="v6" */
(function () {
  if (window.__LINER_MVDB) return;
  window.__LINER_MVDB = 1;

  var LIMIT = 50000;          // حداکثر تعداد شاخه‌ی قابل تبدیل به بازی‌های دیتابیس
  var MV = { id: null, busy: false };

  LU.css(
    '#mvm{position:fixed;inset:0;z-index:9990;background:rgba(0,0,0,.65);display:flex;align-items:center;justify-content:center;padding:12px}' +
    '#mvm[hidden]{display:none}' +
    '#mvm .tyb{width:min(480px,100%);max-height:92dvh;overflow:auto}' +
    '#mvm button{width:100%;margin:4px 0}'
  );
  LU.html('body', 'beforeend',
    '<div id="mvm" hidden><div class="tyb" role="dialog" aria-modal="true" aria-labelledby="mvt">' +
    '<h3 id="mvt"></h3><div id="mvb"></div><div class="meta" id="mvi"></div>' +
    '<button id="mvx">لغو</button></div></div>');

  function closeMv() { if (MV.busy) return; $('mvm').hidden = true; MV.id = null; $('mvi').textContent = ''; }
  $('mvx').onclick = closeMv;
  $('mvm').onclick = function (e) { if (e.target === this) closeMv(); };

  /* ---------- ساخت بازی‌های PGN از درخت لاین (هر شاخه = یک بازی) ---------- */
  function lineBlocks(l) {
    var f = (l.fen || '').split(' '), turn = f[1] || 'w', num = parseInt(f[5], 10) || 1;
    var nm = String(l.name || 'line').replace(/"/g, "'"), paths = [];
    (function w(n, p) {
      if (paths.length >= LIMIT) return;
      if (!n.c.length) { if (p.length) paths.push(p); return; }
      n.c.forEach(function (x) { w(x, p.concat([x])); });
    })(l.tree, []);
    return paths.map(function (p, i) {
      var t = turn, n = num, first = true, mv = [];
      p.forEach(function (nd) {
        if (t === 'w') mv.push(n + '. ' + nd.san);
        else { mv.push(first ? n + '... ' + nd.san : nd.san); n++; }
        first = false; t = (t === 'w') ? 'b' : 'w';
      });
      var h = '[Event "' + nm + '"]\n[Site "Patterner"]\n[White "' + nm + '"]\n[Black "شاخه ' + (i + 1) + '"]\n[Result "*"]\n';
      if (l.fen) h += '[SetUp "1"]\n[FEN "' + l.fen + '"]\n';
      return h + '\n' + mv.join(' ') + ' *\n';
    });
  }

