  function dbSave(name, blocks, onProg) {
    return dbIndex(blocks, onProg).then(function (rec) {
      if (!rec.games.length) throw new Error('بازی معتبری ساخته نشد.');
      var base = name, k = 2;
      while (DBS.some(function (d) { return d.name === name; })) name = base + ' (' + (k++) + ')';
      var id = 'd' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
      rec.id = id;
      var meta = { id: id, name: name, n: rec.games.length, u: rec.P.length, ts: Date.now() };
      return dbPut(meta, rec).then(function () {
        DBC[id] = rec;
        DBS = DBS.filter(function (d) { return d.id !== id; }).concat([meta]).sort(function (a, b) { return a.ts - b.ts; });
        return meta;
      });
    });
  }

  /* ---------- انتقال ---------- */
  function openMv(id) {
    var l = byId(id); if (!l) return;
