/* LINER-UPDATE id="practice-auto-next-v1" title="تمرین چندلاینه: رفتن خودکار به لاین بعدی و توقف فقط بعد از تموم شدن همه" base="v6" */
(function () {
  if (window.__LINER_PAN) return;
  window.__LINER_PAN = 1;

  var DELAY = 2200;      // مکث کوتاه برای خوندن نتیجه‌ی لاین، قبل از رفتن به لاین بعدی
  var PQ = null;         // نوبت‌بندی لاین‌های انتخاب‌شده: {k, ids, done}

  function ids(set) {
    return set.filter(function (l) { return l && l.tree && l.tree.c.length; }).map(function (l) { return l.id; });
  }
  function find(set, id) { return set.filter(function (l) { return l.id === id; })[0]; }

  // لاین بعدیِ تمرین‌نشده به ترتیب (بعد از لاین فعلی، دورزنان)
  function nextId(fromId) {
    var n = PQ.ids.length, i = PQ.ids.indexOf(fromId), j, id;
    for (j = 1; j <= n; j++) {
