      // دکمه‌ی «لاین بعدی»
      var cur = P && P.line && P.line.id, nid = nextId(cur);
      if (!nid) {
        var left = PQ.ids.filter(function (x) { return !PQ.done[x]; });
        if (left.length === 0) { PQ.done = {}; nid = key[0]; toast('یک دور کامل شد؛ دوباره از اول.'); }
        else { toast('این آخرین لاین باقی‌مونده‌ست.'); return; }
